#!/usr/bin/env node

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const CITY_LEDGER = '.fastops/city-ledger.js';
const WORKTREES_DIR = '.city-worktrees';
const CUTOFF_HOURS = 24;

function findStaleWorktrees() {
  const worktrees = [];
  try {
    const dirs = fs.readdirSync(WORKTREES_DIR);
    for (const dir of dirs) {
      const worktreePath = path.join(WORKTREES_DIR, dir);
      const stats = fs.statSync(worktreePath);
      const ageMs = Date.now() - stats.mtime.getTime();
      const ageHours = ageMs / (1000 * 60 * 60);
      
      if (ageHours > CUTOFF_HOURS) {
        worktrees.push({ path: worktreePath, name: dir, ageHours });
      }
    }
  } catch (err) {
    console.error('Error scanning worktrees:', err.message);
  }
  return worktrees;
}

function extractGitData(worktreePath) {
  try {
    const diff = execSync('git diff HEAD', { cwd: worktreePath, encoding: 'utf8' }).trim();
    const log = execSync('git log --oneline -10', { cwd: worktreePath, encoding: 'utf8' }).trim();
    return { diff, log };
  } catch (err) {
    return { diff: '', log: '' };
  }
}

function appendToLedger(compaction) {
  try {
    const ledger = require(`../${CITY_LEDGER}`);
    ledger.append('worktree-compacted', compaction);
  } catch (err) {
    console.error('Failed to append to ledger:', err.message);
  }
}

function removeWorktree(worktreePath) {
  try {
    execSync(`git worktree remove "${worktreePath}"`, { encoding: 'utf8' });
    return true;
  } catch (err) {
    console.error('Failed to remove worktree:', err.message);
    return false;
  }
}

function main() {
  const dryRun = process.argv.includes('--dry-run');
  const staleWorktrees = findStaleWorktrees();
  
  console.log(`Found ${staleWorktrees.length} stale worktrees`);
  
  for (const worktree of staleWorktrees) {
    console.log(`Processing ${worktree.name} (${worktree.ageHours.toFixed(1)}h old)`);
    
    const gitData = extractGitData(worktree.path);
    const compaction = {
      timestamp: new Date().toISOString(),
      worktree: worktree.name,
      ageHours: worktree.ageHours,
      diffLines: gitData.diff.split('\n').length,
      commits: gitData.log.split('\n').filter(l => l.length > 0).length,
      diff: gitData.diff.substring(0, 1000), // truncate for ledger
      log: gitData.log
    };
    
    if (dryRun) {
      console.log(`[DRY RUN] Would compact:`, compaction);
    } else {
      appendToLedger(compaction);
      if (removeWorktree(worktree.path)) {
        console.log(`Compacted and removed ${worktree.name}`);
      }
    }
  }
}

if (require.main === module) {
  main();
}

module.exports = { findStaleWorktrees, extractGitData, appendToLedger, removeWorktree };

